/* =========================================================
   REÇUS — générateur de reçus intégré à l'admin (ex-jcrecu).
   Chaque reçu est enregistré dans la table Supabase `receipts`
   (numéro automatique, historique) puis exporté en JPG.
   Chargé uniquement par admin.html, après app.js.
   ========================================================= */
const RECU_LOGO_SRC = "data:image/png;base64,";
const RECU_DEFAULT_COMPANY = {
  name: 'JC Multimedia',
  address: '123, Rue Lambert, Juvénat, Pétion-Ville',
  phones: '+509 34 43 2139 / 42 75 5464',
  email: ''
};
const RECU_DEFAULT_PAYMENT = {
  moncash: '+509 34 43 2139',
  natcash: '+509 42 75 5464',
  accountName: 'Joseph Roosvelt Jean Charles'
};

let recuLogoImg = null;
let recuLogoReady = false;
let recuState = null;
let recuHistory = [];
let recuNextNumberHint = null;
let recuDrawPending = false;

function recuLoadLogo(){
  if(recuLogoImg) return;
  recuLogoImg = new Image();
  recuLogoImg.onload = () => { recuLogoReady = true; recuScheduleDraw(); };
  recuLogoImg.src = RECU_LOGO_SRC;
}

function recuBlankState(base){
  return {
    id: null,
    number: null,
    orderId: null,
    orderCode: null,
    issuedOn: new Date().toISOString().slice(0,10),
    clientName: '', clientCompany: '', clientPhone: '', clientAddress: '',
    currency: 'HTG',
    items: [{ name:'', description:'', qty:1, price:0 }],
    taxPercent: 0, discount: 0, deliveryFee: 0, depositPercent: 75,
    company: { ...RECU_DEFAULT_COMPANY, ...((base && base.company) || {}) },
    payment: { ...RECU_DEFAULT_PAYMENT, ...((base && base.payment) || {}) },
    signerName: (base && base.signerName) || ''
  };
}

function recuFromRow(r){
  return {
    id: r.id,
    number: r.number,
    orderId: r.order_id || null,
    orderCode: (r.orders && r.orders.code) || null,
    issuedOn: r.issued_on,
    clientName: r.client_name || '', clientCompany: r.client_company || '',
    clientPhone: r.client_phone || '', clientAddress: r.client_address || '',
    currency: r.currency === '$' ? '$' : 'HTG',
    items: (Array.isArray(r.items) && r.items.length ? r.items : [{ name:'', description:'', qty:1, price:0 }])
      .map(i => ({ name: i.name || '', description: i.description || '', qty: Number(i.qty)||0, price: Number(i.price)||0 })),
    taxPercent: Number(r.tax_percent)||0, discount: Number(r.discount)||0,
    deliveryFee: Number(r.delivery_fee)||0, depositPercent: Number(r.deposit_percent ?? 75),
    company: { ...RECU_DEFAULT_COMPANY, ...(r.company || {}) },
    payment: { ...RECU_DEFAULT_PAYMENT, ...(r.payment_info || {}) },
    signerName: r.signer_name || ''
  };
}

function recuTotals(st){
  const subtotal = st.items.reduce((a,i) => a + (Number(i.qty)||0) * (Number(i.price)||0), 0);
  const taxAmount = subtotal * ((Number(st.taxPercent)||0) / 100);
  const total = subtotal + taxAmount - (Number(st.discount)||0) + (Number(st.deliveryFee)||0);
  const depositAmount = total * ((Number(st.depositPercent)||0) / 100);
  return { subtotal, taxAmount, total, depositAmount, balanceAmount: total - depositAmount };
}

function recuMoney(n, cur){
  const v = (Math.round((Number(n)||0) * 100) / 100)
    .toLocaleString('fr-FR', { minimumFractionDigits:2, maximumFractionDigits:2 })
    .replace(/[\u202f\u00a0]/g, ' ');
  return `${v} ${cur}`;
}
// Code du reçu, sur le modèle des codes de commande (JC-PRC…, JC-SRC…) : JC-REC1001, JC-REC1002…
function recuNumberLabel(n){ return n ? 'JC-REC' + n : '—'; }
function recuFormatDate(str){
  if(!str) return '';
  const [y,m,d] = String(str).split('-');
  return `${d}/${m}/${y}`;
}

/* ---------- Onglet ---------- */
async function renderAdminRecus(){
  const el = document.getElementById('adminTab-recus');
  if(!el) return;
  recuLoadLogo();
  if(!SUPABASE_ENABLED){
    el.innerHTML = `<div class="admin-note">⚠️ Les reçus nécessitent que Supabase soit configuré.</div>`;
    return;
  }
  if(!recuState){
    el.innerHTML = `<p class="card-sub">Chargement…</p>`;
    await recuLoadHistory();
    // Reprend l'entreprise, les moyens de paiement et le signataire du dernier reçu
    const last = recuHistory[0];
    recuState = recuBlankState(last ? recuFromRow(last) : null);
  } else {
    recuLoadHistory().then(recuRenderHistory);
  }
  recuRenderShell();
}

async function recuLoadHistory(){
  try{
    const { data, error } = await db.from('receipts').select('*, orders(code)').order('number', { ascending:false }).limit(200);
    if(error) throw error;
    recuHistory = data || [];
    recuNextNumberHint = recuHistory[0] ? Number(recuHistory[0].number) + 1 : null;
  }catch(e){
    console.error('recuLoadHistory:', e);
    recuHistory = [];
  }
}

function recuField(id, label, value, opts={}){
  const type = opts.type || 'text';
  const extra = opts.extra || '';
  return `<div class="form-field"><label for="${id}">${label}</label><input type="${type}" id="${id}" value="${escapeHtml(String(value ?? ''))}" ${extra} oninput="recuReadForm()"></div>`;
}

function recuCatalogOptions(){
  const prods = (CATALOG && CATALOG.products) || [];
  const servs = (CATALOG && CATALOG.services) || [];
  const opt = (kind, i) => `<option value="${kind}:${escapeHtml(String(i.id))}">${escapeHtml(i.name || '(sans nom)')}</option>`;
  return `<option value="">+ Ajouter depuis le catalogue…</option>`
    + (prods.length ? `<optgroup label="Produits">${prods.map(i => opt('products', i)).join('')}</optgroup>` : '')
    + (servs.length ? `<optgroup label="Services">${servs.map(i => opt('services', i)).join('')}</optgroup>` : '');
}

function recuRenderShell(){
  const el = document.getElementById('adminTab-recus');
  const st = recuState;
  const cur = st.currency;
  const numberText = st.number
    ? `Reçu ${recuNumberLabel(st.number)} — modification`
    : `Nouveau reçu — code attribué automatiquement à l'enregistrement${recuNextNumberHint ? ` (prochain : ${recuNumberLabel(recuNextNumberHint)})` : ''}`;
  const orderText = st.orderCode ? `<br>Lié à la commande <strong>${escapeHtml(st.orderCode)}</strong>` : '';
  el.innerHTML = `
    <div class="recu-layout">
      <div class="recu-form">
        <div class="admin-note" style="margin-bottom:12px;">${numberText}${orderText}</div>

        <h3 class="recu-h">Reçu</h3>
        ${recuField('r-date', "Date d'émission", st.issuedOn, { type:'date' })}
        <div class="form-field">
          <label>Devise</label>
          <div style="display:flex; gap:6px;">
            <button type="button" class="opt-btn ${cur==='HTG'?'selected':''}" onclick="recuSetCurrency('HTG')">Gourdes (HTG)</button>
            <button type="button" class="opt-btn ${cur==='$'?'selected':''}" onclick="recuSetCurrency('$')">Dollars ($)</button>
          </div>
        </div>

        <h3 class="recu-h">Facturé à (client)</h3>
        ${recuField('r-cname', 'Nom du client', st.clientName)}
        ${recuField('r-ccompany', 'Entreprise (optionnel)', st.clientCompany)}
        ${recuField('r-cphone', 'Téléphone', st.clientPhone, { extra:'inputmode="tel" placeholder="+509 __ __ ____"' })}
        ${recuField('r-caddress', 'Adresse', st.clientAddress)}

        <h3 class="recu-h">Articles / services</h3>
        <div id="recuItems"></div>
        <div class="form-field">
          <select id="r-catalog" onchange="recuAddFromCatalog(this.value); this.value='';">${recuCatalogOptions()}</select>
        </div>
        <button type="button" class="btn btn-ghost btn-block" onclick="recuAddItem()">+ Ajouter une ligne vide</button>

        <h3 class="recu-h">Totaux</h3>
        <div class="recu-row">
          ${recuField('r-tax', 'Taxe (%)', st.taxPercent, { type:'number', extra:'step="0.1" min="0"' })}
          ${recuField('r-discount', `Remise (${cur})`, st.discount, { type:'number', extra:'step="0.01" min="0"' })}
        </div>
        <div class="recu-row">
          ${recuField('r-delivery', `Livraison (${cur})`, st.deliveryFee, { type:'number', extra:'step="0.01" min="0"' })}
          ${recuField('r-deposit', 'Acompte requis (%)', st.depositPercent, { type:'number', extra:'step="1" min="0" max="100"' })}
        </div>
        <div class="admin-note" id="recuTotalsNote"></div>

        <h3 class="recu-h">Signature</h3>
        ${recuField('r-signer', 'Signataire', st.signerName, { extra:'placeholder="Ex. Jonas Casimir"' })}

        <details class="recu-details">
          <summary>Entreprise et moyens de paiement</summary>
          ${recuField('r-company', "Nom de l'entreprise", st.company.name)}
          ${recuField('r-companyaddr', 'Adresse', st.company.address)}
          ${recuField('r-companyphones', 'Téléphones', st.company.phones)}
          ${recuField('r-companyemail', 'Email (optionnel)', st.company.email)}
          ${recuField('r-moncash', 'MonCash', st.payment.moncash)}
          ${recuField('r-natcash', 'NatCash', st.payment.natcash)}
          ${recuField('r-account', 'Nom du compte', st.payment.accountName)}
          <p class="card-sub">Ces informations sont reprises automatiquement pour le reçu suivant.</p>
        </details>

        <div class="recu-actions">
          <button class="btn btn-wa btn-block" id="recuShareBtn" onclick="recuSaveAndExport('share')">Enregistrer + partager l'image (WhatsApp)</button>
          <button class="btn btn-primary btn-block" id="recuPdfBtn" onclick="recuSaveAndExport('pdf')">Enregistrer + partager en PDF (qualité maximale)</button>
          <button class="btn btn-ghost btn-block" id="recuSaveBtn" onclick="recuSaveAndExport('download')">Enregistrer + télécharger le JPG (pleine résolution)</button>
          <p class="card-sub" style="margin:2px 0 0;">Astuce : le PDF arrive sur WhatsApp sans aucune perte de qualité. Pour l'image, appuyez sur « HD » dans WhatsApp avant l'envoi si l'option s'affiche.</p>
          <button class="btn btn-ghost btn-block" onclick="recuNew()">Nouveau reçu</button>
        </div>
      </div>

      <div class="recu-preview">
        <canvas id="recuCanvas" width="900" height="1125"></canvas>
      </div>
    </div>

    <h3 style="margin:28px 0 8px;">Historique des reçus</h3>
    <div class="form-field"><input type="text" id="recuSearch" placeholder="Rechercher (client, téléphone, code)…" oninput="recuRenderHistory()"></div>
    <div id="recuHistory"></div>
  `;
  recuRenderItems();
  recuRenderHistory();
  recuUpdateTotalsNote();
  recuWaitFontsThenDraw();
}

function recuRenderItems(){
  const box = document.getElementById('recuItems');
  if(!box) return;
  const st = recuState;
  box.innerHTML = st.items.map((it, i) => `
    <div class="recu-item">
      ${st.items.length > 1 ? `<button type="button" class="recu-remove" onclick="recuRemoveItem(${i})">retirer</button>` : ''}
      <div class="form-field"><label>Article / service</label><input type="text" value="${escapeHtml(it.name)}" oninput="recuSetItem(${i},'name',this.value)"></div>
      <div class="form-field"><label>Description</label><input type="text" value="${escapeHtml(it.description)}" oninput="recuSetItem(${i},'description',this.value)"></div>
      <div class="recu-row">
        <div class="form-field"><label>Quantité</label><input type="number" min="0" step="1" value="${it.qty}" oninput="recuSetItem(${i},'qty',this.value)"></div>
        <div class="form-field"><label>Prix unitaire (${st.currency})</label><input type="number" min="0" step="0.01" value="${it.price}" oninput="recuSetItem(${i},'price',this.value)"></div>
      </div>
    </div>
  `).join('');
}

function recuReadForm(){
  const st = recuState;
  if(!st) return;
  const v = id => { const e = document.getElementById(id); return e ? e.value : ''; };
  const n = id => parseFloat(v(id)) || 0;
  st.issuedOn = v('r-date') || st.issuedOn;
  st.clientName = v('r-cname').trim();
  st.clientCompany = v('r-ccompany').trim();
  st.clientPhone = v('r-cphone').trim();
  st.clientAddress = v('r-caddress').trim();
  st.taxPercent = n('r-tax');
  st.discount = n('r-discount');
  st.deliveryFee = n('r-delivery');
  st.depositPercent = v('r-deposit') === '' ? 0 : n('r-deposit');
  st.signerName = v('r-signer').trim();
  st.company = { name: v('r-company').trim() || 'JC Multimedia', address: v('r-companyaddr').trim(), phones: v('r-companyphones').trim(), email: v('r-companyemail').trim() };
  st.payment = { moncash: v('r-moncash').trim(), natcash: v('r-natcash').trim(), accountName: v('r-account').trim() };
  recuUpdateTotalsNote();
  recuScheduleDraw();
}

function recuSetItem(i, field, value){
  const it = recuState.items[i];
  if(!it) return;
  it[field] = (field === 'qty' || field === 'price') ? (parseFloat(value) || 0) : value;
  recuUpdateTotalsNote();
  recuScheduleDraw();
}
function recuAddItem(){
  recuState.items.push({ name:'', description:'', qty:1, price:0 });
  recuRenderItems(); recuUpdateTotalsNote(); recuScheduleDraw();
}
function recuRemoveItem(i){
  recuState.items.splice(i, 1);
  if(!recuState.items.length) recuState.items.push({ name:'', description:'', qty:1, price:0 });
  recuRenderItems(); recuUpdateTotalsNote(); recuScheduleDraw();
}
function recuAddFromCatalog(value){
  if(!value) return;
  const sep = value.indexOf(':');
  const kind = value.slice(0, sep), id = value.slice(sep + 1);
  const list = (CATALOG && CATALOG[kind]) || [];
  const item = list.find(x => String(x.id) === id);
  if(!item) return;
  const htg = kind === 'services' ? Number(item.startingPrice)||0 : Number(item.price)||0;
  // Le catalogue est en gourdes ; si le reçu est en dollars, on convertit avec le taux du site.
  const price = recuState.currency === '$'
    ? Math.round((htg / (SETTINGS.exchangeRate || 1)) * 100) / 100
    : htg;
  const line = { name: item.name || '', description: (item.utility || item.description || '').slice(0, 120), qty: 1, price };
  const last = recuState.items[recuState.items.length - 1];
  if(last && !last.name && !last.description && !Number(last.price)) recuState.items[recuState.items.length - 1] = line;
  else recuState.items.push(line);
  recuRenderItems(); recuUpdateTotalsNote(); recuScheduleDraw();
}
function recuSetCurrency(cur){
  if(recuState.currency === cur) return;
  recuReadForm();
  recuState.currency = cur;
  recuRenderShell();
  showToast(cur === 'HTG'
    ? "Devise : gourdes. Les montants saisis ne sont pas convertis."
    : "Devise : dollars. Les montants saisis ne sont pas convertis.");
}
function recuUpdateTotalsNote(){
  const el = document.getElementById('recuTotalsNote');
  if(!el) return;
  const t = recuTotals(recuState);
  const c = recuState.currency;
  el.innerHTML = `Total : <strong>${escapeHtml(recuMoney(t.total, c))}</strong> — acompte ${escapeHtml(recuMoney(t.depositAmount, c))}, solde ${escapeHtml(recuMoney(t.balanceAmount, c))}`;
}

function recuNew(){
  recuReadForm();
  recuState = recuBlankState(recuState);
  recuRenderShell();
  window.scrollTo({ top: document.getElementById('adminTab-recus').offsetTop - 20, behavior:'smooth' });
}

/* ---------- Historique ---------- */
function recuRenderHistory(){
  const box = document.getElementById('recuHistory');
  if(!box) return;
  const qEl = document.getElementById('recuSearch');
  const q = (qEl ? qEl.value : '').trim().toLowerCase();
  const rows = recuHistory.filter(r => !q
    || (r.client_name || '').toLowerCase().includes(q)
    || (r.client_phone || '').toLowerCase().includes(q)
    || ((r.orders && r.orders.code) || '').toLowerCase().includes(q)
    || recuNumberLabel(r.number).toLowerCase().includes(q));
  if(!rows.length){
    box.innerHTML = `<p class="card-sub">${recuHistory.length ? 'Aucun reçu ne correspond.' : 'Aucun reçu enregistré pour le moment.'}</p>`;
    return;
  }
  box.innerHTML = rows.map(r => `
    <div class="admin-item-card recu-hist">
      <div class="recu-hist-main">
        <strong>${recuNumberLabel(r.number)}</strong> — ${escapeHtml(r.client_name || '(sans nom)')}
        <div class="card-sub">${escapeHtml(recuFormatDate(r.issued_on))} · ${escapeHtml(recuMoney(r.total, r.currency === '$' ? '$' : 'HTG'))}${r.orders && r.orders.code ? ` · commande ${escapeHtml(r.orders.code)}` : ''}</div>
      </div>
      <div style="display:flex; gap:6px;">
        <button class="btn btn-ghost" onclick="recuOpen('${escapeHtml(String(r.id))}')">Ouvrir</button>
        <button class="btn btn-ghost" onclick="recuDelete('${escapeHtml(String(r.id))}')" aria-label="Supprimer">🗑</button>
      </div>
    </div>
  `).join('');
}
function recuOpen(id){
  const row = recuHistory.find(r => String(r.id) === String(id));
  if(!row) return;
  recuState = recuFromRow(row);
  recuRenderShell();
  window.scrollTo({ top: document.getElementById('adminTab-recus').offsetTop - 20, behavior:'smooth' });
}
async function recuDelete(id){
  const row = recuHistory.find(r => String(r.id) === String(id));
  if(!row) return;
  if(!confirm(`Supprimer définitivement le reçu ${recuNumberLabel(row.number)} ?`)) return;
  try{
    const { error } = await db.from('receipts').delete().eq('id', id);
    if(error) throw error;
    recuHistory = recuHistory.filter(r => String(r.id) !== String(id));
    if(recuState && String(recuState.id) === String(id)){ recuState = recuBlankState(recuState); recuRenderShell(); }
    else recuRenderHistory();
    showToast('Reçu supprimé');
  }catch(e){
    console.error(e);
    showToast('Échec de la suppression');
  }
}

/* ---------- Enregistrement + export ---------- */
async function recuSaveAndExport(mode){
  recuReadForm();
  const st = recuState;
  if(!st.clientName){ showToast('Indiquez le nom du client'); return; }
  const items = st.items.filter(i => i.name.trim() || i.description.trim() || Number(i.price));
  if(!items.length){ showToast('Ajoutez au moins un article ou service'); return; }

  const btn = document.getElementById(mode === 'share' ? 'recuShareBtn' : mode === 'pdf' ? 'recuPdfBtn' : 'recuSaveBtn');
  const label = btn ? btn.textContent : '';
  if(btn){ btn.disabled = true; btn.textContent = 'Enregistrement…'; }
  try{
    const t = recuTotals({ ...st, items });
    const row = {
      issued_on: st.issuedOn,
      client_name: st.clientName,
      client_company: st.clientCompany || null,
      client_phone: st.clientPhone || null,
      client_address: st.clientAddress || null,
      currency: st.currency,
      items: items.map(i => ({ name: i.name.trim(), description: i.description.trim(), qty: Number(i.qty)||0, price: Number(i.price)||0 })),
      tax_percent: st.taxPercent, discount: st.discount, delivery_fee: st.deliveryFee, deposit_percent: st.depositPercent,
      subtotal: Math.round(t.subtotal * 100) / 100,
      total: Math.round(t.total * 100) / 100,
      company: st.company,
      payment_info: st.payment,
      signer_name: st.signerName || null,
      order_id: st.orderId || null,
      updated_at: new Date().toISOString()
    };
    let saved;
    if(st.id){
      const { data, error } = await db.from('receipts').update(row).eq('id', st.id).select('*, orders(code)').single();
      if(error) throw error;
      saved = data;
    } else {
      const { data, error } = await db.from('receipts').insert(row).select('*, orders(code)').single();
      if(error) throw error;
      saved = data;
    }
    recuState = recuFromRow(saved);
    const idx = recuHistory.findIndex(r => String(r.id) === String(saved.id));
    if(idx >= 0) recuHistory[idx] = saved; else recuHistory.unshift(saved);
    recuHistory.sort((a,b) => Number(b.number) - Number(a.number));
    recuNextNumberHint = Number(recuHistory[0].number) + 1;
    recuRenderShell();
    await recuWaitFontsThenDraw();
    await recuExport(mode);
  }catch(e){
    console.error('recuSaveAndExport:', e);
    showToast("Échec de l'enregistrement — vérifiez votre connexion.");
    if(btn){ btn.disabled = false; btn.textContent = label; }
  }
}

/* ---------- Export : JPG (pleine résolution ou format WhatsApp) et PDF ----------
   WhatsApp réduit toute photo à ~1600 px sur son plus grand côté puis la
   recompresse. Pour l'image partagée, on dessine DIRECTEMENT le reçu à
   1600 px (texte net, aucune réduction par WhatsApp) en qualité maximale.
   Le PDF, lui, est envoyé par WhatsApp comme document : aucune compression. */
const RECU_WHATSAPP_MAX_SIDE = 1600;

function recuRenderBlob(maxSide, quality){
  const c = document.createElement('canvas');
  recuDraw({ canvas: c, maxSide });
  return new Promise(resolve => c.toBlob(b => resolve({ blob: b, width: c.width, height: c.height }), 'image/jpeg', quality));
}

// PDF d'une page contenant l'image JPEG (format A4 en largeur), sans bibliothèque
async function recuBuildPdf(){
  const { blob, width, height } = await recuRenderBlob(null, 0.95);
  if(!blob) return null;
  const jpg = new Uint8Array(await blob.arrayBuffer());
  const pageW = 595.28, pageH = Math.round(pageW * height / width * 100) / 100;
  const enc = new TextEncoder();
  const parts = []; const offsets = []; let len = 0;
  const push = (data) => { const u = typeof data === 'string' ? enc.encode(data) : data; parts.push(u); len += u.length; };
  const obj = (n, body) => { offsets[n] = len; push(`${n} 0 obj\n${body}\nendobj\n`); };
  push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  obj(1, '<< /Type /Catalog /Pages 2 0 R >>');
  obj(2, '<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  obj(3, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageW} ${pageH}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);
  offsets[4] = len;
  push(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${width} /Height ${height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);
  push(jpg);
  push('\nendstream\nendobj\n');
  const content = `q ${pageW} 0 0 ${pageH} 0 0 cm /Im0 Do Q`;
  obj(5, `<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
  const xrefPos = len;
  let xref = 'xref\n0 6\n0000000000 65535 f \n';
  for(let i = 1; i <= 5; i++) xref += String(offsets[i]).padStart(10, '0') + ' 00000 n \n';
  push(xref + `trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF\n`);
  return new Blob(parts, { type: 'application/pdf' });
}

async function recuShareOrDownload(blob, fileName, type){
  const label = recuNumberLabel(recuState.number);
  const file = new File([blob], fileName, { type });
  if(navigator.canShare && navigator.canShare({ files:[file] })){
    try{
      await navigator.share({ files:[file], title: `Reçu ${label}` });
      showToast('Reçu enregistré');
      return;
    }catch(e){
      if(e && e.name === 'AbortError'){ showToast('Reçu enregistré (partage annulé)'); return; }
    }
  }
  showToast("Partage non disponible ici : le fichier est téléchargé.");
  recuDownload(blob, fileName);
}
function recuDownload(blob, fileName){
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = fileName;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

async function recuExport(mode){
  const base = `recu-${recuNumberLabel(recuState.number)}`;
  try{
    if(mode === 'pdf'){
      const pdf = await recuBuildPdf();
      if(!pdf){ showToast("Impossible de créer le PDF"); return; }
      await recuShareOrDownload(pdf, base + '.pdf', 'application/pdf');
      return;
    }
    if(mode === 'share'){
      const { blob } = await recuRenderBlob(RECU_WHATSAPP_MAX_SIDE, 1.0);
      if(!blob){ showToast("Impossible de créer l'image"); return; }
      await recuShareOrDownload(blob, base + '.jpg', 'image/jpeg');
      return;
    }
    const { blob } = await recuRenderBlob(null, 0.96);
    if(!blob){ showToast("Impossible de créer l'image"); return; }
    recuDownload(blob, base + '.jpg');
    showToast(`Reçu ${recuNumberLabel(recuState.number)} enregistré`);
  }catch(e){
    console.error('recuExport:', e);
    showToast("Impossible de créer le fichier du reçu");
  }
}

/* ---------- Dessin du reçu (modèle « facture » marine et orange) ---------- */
function recuScheduleDraw(){
  if(recuDrawPending) return;
  recuDrawPending = true;
  requestAnimationFrame(() => { recuDrawPending = false; recuDraw(); });
}
async function recuWaitFontsThenDraw(){
  try{
    if(document.fonts && document.fonts.load){
      await Promise.all([
        document.fonts.load('800 38px Poppins'),
        document.fonts.load('700 17px Poppins'),
        document.fonts.load('600 18px Poppins'),
        document.fonts.load('15px Poppins'),
        document.fonts.load('500 28px Poppins'),
        document.fonts.load('600 38px "Dancing Script"')
      ]);
    }
  }catch(e){}
  recuDraw();
}

function recuDraw(opts){
  opts = opts || {};
  const canvas = opts.canvas || document.getElementById('recuCanvas');
  if(!canvas || !recuState) return;
  const ctx = canvas.getContext('2d');
  const st = recuState;
  const W = 900;
  const cur = st.currency;
  const receiptNo = st.number ? recuNumberLabel(st.number) : (recuNextNumberHint ? recuNumberLabel(recuNextNumberHint) : 'JC-REC…');
  const date = recuFormatDate(st.issuedOn);
  const company = st.company.name || 'JC Multimedia';
  const navy = '#16296B', orange = '#F79A0E', ink = '#111111', muted = '#4A4A55', gray = '#E3E2EA';
  const M = 46;                 // marge gauche / droite
  const tX = M, tW = W - 2*M;   // largeur utile

  function wrapText(text, maxWidth, font){
    ctx.font = font;
    const words = String(text || '').split(' ');
    const lines = []; let line = '';
    for(const w of words){
      const test = line ? line + ' ' + w : w;
      if(ctx.measureText(test).width > maxWidth && line){ lines.push(line); line = w; }
      else line = test;
    }
    if(line) lines.push(line);
    return lines.length ? lines : [''];
  }
  function fitText(text, maxWidth, font){
    ctx.font = font;
    let s = String(text || '');
    if(ctx.measureText(s).width <= maxWidth) return s;
    while(s.length > 1 && ctx.measureText(s + '…').width > maxWidth) s = s.slice(0, -1);
    return s + '…';
  }
  function fitFont(text, maxWidth, weight, size, family, minSize){
    // Réduit la taille jusqu'à ce que le texte tienne (au lieu de le couper)
    family = family || 'Poppins'; minSize = minSize || 10;
    let sz = size;
    ctx.font = `${weight} ${sz}px ${family}`;
    while(sz > minSize && ctx.measureText(String(text || '')).width > maxWidth){
      sz -= 0.5; ctx.font = `${weight} ${sz}px ${family}`;
    }
    return ctx.font;
  }
  function spaced(text, x, y, spacing){
    // Texte avec espacement des lettres (compatible tous navigateurs)
    let cx = x;
    for(const ch of String(text)){ ctx.fillText(ch, cx, y); cx += ctx.measureText(ch).width + spacing; }
  }

  /* ---------- Mise en page : calcul des hauteurs ---------- */
  // Colonnes du tableau (alignées à gauche, comme le modèle)
  const colDesc = tX + 32, colQty = tX + tW*0.50, colPU = tX + tW*0.60, colSub = tX + tW*0.79;
  const descMaxW = colQty - colDesc - 40;
  const rowsMeta = st.items.map(s => {
    const nameLines = wrapText(s.name || '—', descMaxW, '500 17px Poppins');
    const descLines = s.description ? wrapText(s.description, descMaxW, '14px Poppins') : [];
    const h = Math.max(56, 22 + nameLines.length * 22 + descLines.length * 19 + 12);
    return { ...s, nameLines, descLines, h };
  });

  // Bloc « Facturé à » (aligné à droite)
  const clientLines = [];
  if(st.clientCompany) clientLines.push(st.clientCompany);
  if(st.clientPhone) clientLines.push('Tél : ' + st.clientPhone);
  if(st.clientAddress) wrapText(st.clientAddress, 400, '15px Poppins').forEach(l => clientLines.push(l));
  if(st.orderCode) clientLines.push('Commande : ' + st.orderCode);
  const clientTop = 318;
  const clientBottom = clientTop + 48 + clientLines.length * 22;

  const tableTop = Math.max(clientBottom + 40, 470);
  const headH = 66;
  const tableBottom = tableTop + headH + rowsMeta.reduce((a, r) => a + r.h, 0);

  const t = recuTotals(st);
  const totRows = [['Sous-total', recuMoney(t.subtotal, cur)]];
  if(Number(st.taxPercent)) totRows.push(['Taxe (' + (Number(st.taxPercent)||0) + ' %)', recuMoney(t.taxAmount, cur)]);
  if(Number(st.discount)) totRows.push(['Remise', '-' + recuMoney(st.discount, cur)]);
  if(Number(st.deliveryFee)) totRows.push(['Livraison', recuMoney(st.deliveryFee, cur)]);
  const rowH = 54;
  const bottomTop = tableBottom + 56;
  const totBoxH = totRows.length * rowH + (rowH + 6) + 14 + 2 * 44;   // lignes + TOTAL + acompte/solde
  const payBlockH = 250;
  const contactTop = bottomTop + Math.max(totBoxH, payBlockH) + 80;
  const contentBottom = contactTop + 190;
  const H = Math.max(contentBottom + 110, Math.round(W * 1.414));

  // Échelle : 3 (pleine résolution) ou ajustée pour que le plus grand côté
  // fasse exactement opts.maxSide pixels (version WhatsApp).
  const SCALE = opts.maxSide ? Math.min(3, opts.maxSide / Math.max(W, H)) : 3;
  canvas.width = Math.round(W * SCALE);
  canvas.height = Math.round(H * SCALE);
  ctx.setTransform(SCALE, 0, 0, SCALE, 0, 0);
  ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
  ctx.textBaseline = 'alphabetic';

  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, W, H);

  /* ---------- En-tête : formes diagonales ---------- */
  // Bord bas du bandeau marine : droite de (49, 346) à (900, 95)
  const edgeY = x => 346 - (346 - 95) * (x - 49) / (W - 49);
  ctx.fillStyle = navy;
  ctx.beginPath();
  ctx.moveTo(0, 0); ctx.lineTo(W, 0); ctx.lineTo(W, 95); ctx.lineTo(49, 346); ctx.lineTo(0, 140);
  ctx.closePath(); ctx.fill();
  // Petit triangle orange à gauche
  ctx.fillStyle = orange;
  ctx.beginPath(); ctx.moveTo(0, 140); ctx.lineTo(49, 346); ctx.lineTo(0, 288); ctx.closePath(); ctx.fill();
  // Bande orange à droite, collée au bandeau
  ctx.beginPath();
  ctx.moveTo(470, edgeY(470)); ctx.lineTo(W, 95); ctx.lineTo(W, 152); ctx.lineTo(486, edgeY(486) + 56);
  ctx.closePath(); ctx.fill();

  // Logo dans une pastille blanche
  const lcX = W - M - 52, lcY = 66, lr = 50;
  ctx.fillStyle = '#FFFFFF';
  ctx.beginPath(); ctx.arc(lcX, lcY, lr, 0, Math.PI * 2); ctx.fill();
  if(recuLogoReady && recuLogoImg.naturalWidth){
    const side = lr * 2 - 14;
    const ratio = Math.min(side / recuLogoImg.naturalWidth, side / recuLogoImg.naturalHeight);
    const w = recuLogoImg.naturalWidth * ratio, h = recuLogoImg.naturalHeight * ratio;
    ctx.save();
    ctx.beginPath(); ctx.arc(lcX, lcY, lr - 4, 0, Math.PI * 2); ctx.clip();
    ctx.drawImage(recuLogoImg, lcX - w/2, lcY - h/2, w, h);
    ctx.restore();
  }

  // Titre, entreprise, code et date
  ctx.textAlign = 'left';
  ctx.fillStyle = '#FFFFFF';
  ctx.font = '800 76px Poppins';
  ctx.fillText(fitText('FACTURE', 560, '800 76px Poppins'), 92, 132);
  ctx.font = '500 28px Poppins';
  ctx.fillText(fitText(company, 520, '500 28px Poppins'), 94, 172);
  ctx.font = '500 16px Poppins';
  spaced('REÇU N° : ' + receiptNo, 95, 214, 2.2);
  spaced('DATE : ' + date, 95, 238, 2.2);

  /* ---------- Facturé à ---------- */
  const rX = W - M - 14;
  ctx.textAlign = 'right';
  ctx.fillStyle = ink;
  ctx.font = '600 18px Poppins';
  ctx.fillText('Facturé à :', rX, clientTop);
  fitFont(st.clientName || '—', 560, 700, 38, 'Poppins', 22);
  ctx.fillText(fitText(st.clientName || '—', 560, ctx.font), rX, clientTop + 44);
  ctx.font = '15px Poppins'; ctx.fillStyle = '#222';
  clientLines.forEach((l, i) => ctx.fillText(fitText(l, 560, '15px Poppins'), rX, clientTop + 72 + i * 22));

  /* ---------- Tableau ---------- */
  ctx.fillStyle = navy;
  ctx.fillRect(tX, tableTop, tW, headH);
  ctx.fillStyle = '#FFFFFF';
  ctx.font = '600 18px Poppins';
  ctx.textAlign = 'left';
  const hy = tableTop + headH/2 + 7;
  ctx.fillText('Description', colDesc, hy);
  ctx.textAlign = 'center'; ctx.fillText('Qté', colQty, hy);
  ctx.textAlign = 'left';
  ctx.fillText('Prix unit.', colPU, hy);
  ctx.fillText('Sous-total', colSub, hy);

  let rowY = tableTop + headH;
  rowsMeta.forEach((s, idx) => {
    const rowTotal = (Number(s.qty)||0) * (Number(s.price)||0);
    if(idx % 2 === 1){ ctx.fillStyle = gray; ctx.fillRect(tX, rowY, tW, s.h); }
    const firstY = rowY + 34;
    ctx.textAlign = 'left'; ctx.fillStyle = ink; ctx.font = '500 17px Poppins';
    s.nameLines.forEach((l, i) => ctx.fillText(l, colDesc, firstY + i * 22));
    if(s.descLines.length){
      ctx.font = '14px Poppins'; ctx.fillStyle = muted;
      s.descLines.forEach((l, i) => ctx.fillText(l, colDesc, firstY + s.nameLines.length * 22 + i * 19 - 2));
    }
    ctx.fillStyle = ink; ctx.font = '17px Poppins';
    ctx.textAlign = 'center'; ctx.fillText(String(Number(s.qty)||0), colQty, firstY);
    ctx.textAlign = 'left';
    fitFont(recuMoney(s.price, cur), colSub - colPU - 12, 400, 17);
    ctx.fillText(recuMoney(s.price, cur), colPU, firstY);
    fitFont(recuMoney(rowTotal, cur), tX + tW - colSub - 8, 400, 17);
    ctx.fillText(recuMoney(rowTotal, cur), colSub, firstY);
    ctx.font = '17px Poppins';
    rowY += s.h;
  });

  /* ---------- Totaux (à droite) ---------- */
  const boxX = tX + tW * 0.55, boxW = tW * 0.45;
  const lblX = boxX + 32, valX = boxX + boxW - 24;
  let y = bottomTop;
  totRows.forEach((r, i) => {
    if(i % 2 === 1){ ctx.fillStyle = gray; ctx.fillRect(boxX, y, boxW, rowH); }
    ctx.fillStyle = ink; ctx.textAlign = 'left'; ctx.font = '600 17px Poppins';
    ctx.fillText(r[0], lblX, y + rowH/2 + 6);
    const lw = ctx.measureText(r[0]).width;
    ctx.textAlign = 'right'; fitFont(r[1], valX - lblX - lw - 14, 400, 17);
    ctx.fillText(r[1], valX, y + rowH/2 + 6);
    y += rowH;
  });
  ctx.fillStyle = navy; ctx.fillRect(boxX, y, boxW, rowH + 6);
  ctx.fillStyle = '#FFFFFF'; ctx.textAlign = 'left'; ctx.font = '700 18px Poppins';
  ctx.fillText('TOTAL', lblX, y + (rowH + 6)/2 + 7);
  const totLw = ctx.measureText('TOTAL').width;
  ctx.textAlign = 'right'; fitFont(recuMoney(t.total, cur), valX - lblX - totLw - 16, 700, 21);
  ctx.fillText(recuMoney(t.total, cur), valX, y + (rowH + 6)/2 + 7);
  y += rowH + 6 + 14;
  // Acompte et solde
  ctx.fillStyle = '#FFF3DF'; ctx.fillRect(boxX, y, boxW, 44);
  ctx.fillStyle = ink; ctx.textAlign = 'left'; ctx.font = '600 15px Poppins';
  const depLabel = 'Acompte requis (' + (Number(st.depositPercent)||0) + ' %)';
  ctx.fillText(depLabel, lblX, y + 28);
  const depLw = ctx.measureText(depLabel).width;
  ctx.textAlign = 'right'; fitFont(recuMoney(t.depositAmount, cur), valX - lblX - depLw - 12, 700, 16); ctx.fillStyle = '#B86E00';
  ctx.fillText(recuMoney(t.depositAmount, cur), valX, y + 28);
  y += 44;
  ctx.fillStyle = ink; ctx.textAlign = 'left'; ctx.font = '600 15px Poppins';
  ctx.fillText('Solde à la livraison', lblX, y + 28);
  const solLw = ctx.measureText('Solde à la livraison').width;
  ctx.textAlign = 'right'; fitFont(recuMoney(t.balanceAmount, cur), valX - lblX - solLw - 12, 600, 16);
  ctx.fillText(recuMoney(t.balanceAmount, cur), valX, y + 28);

  /* ---------- Détails de paiement (à gauche) ---------- */
  const pW = boxX - tX - 30;
  let py = bottomTop + 20;
  ctx.textAlign = 'left'; ctx.fillStyle = ink; ctx.font = '700 20px Poppins';
  ctx.fillText('DÉTAILS DE PAIEMENT :', tX + 18, py);
  py += 40;
  function payItem(label, value){
    ctx.fillStyle = ink; ctx.font = '600 16px Poppins';
    ctx.fillText(label, tX + 18, py); py += 22;
    ctx.font = 'italic 16px Poppins'; ctx.fillStyle = '#222';
    ctx.fillText(fitText(value, pW - 18, 'italic 16px Poppins'), tX + 18, py); py += 32;
  }
  if(st.payment.moncash) payItem('MonCash :', st.payment.moncash);
  if(st.payment.natcash) payItem('NatCash :', st.payment.natcash);
  if(st.payment.accountName) payItem('Nom du compte :', st.payment.accountName);
  ctx.font = '13px Poppins'; ctx.fillStyle = muted;
  wrapText("Un acompte d'au moins " + (Number(st.depositPercent)||0) + " % est obligatoire avant le début du travail.", pW - 18, '13px Poppins')
    .forEach(l => { ctx.fillText(l, tX + 18, py); py += 18; });

  /* ---------- Contact (à gauche) ---------- */
  let cy = contactTop;
  ctx.fillStyle = ink; ctx.font = '700 20px Poppins'; ctx.textAlign = 'left';
  ctx.fillText('CONTACTEZ-NOUS', tX + 14, cy);
  cy += 26;
  function icon(kind, cx, cyy){
    ctx.fillStyle = navy; ctx.beginPath(); ctx.arc(cx, cyy, 17, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#FFFFFF'; ctx.fillStyle = '#FFFFFF'; ctx.lineWidth = 1.8;
    if(kind === 'phone'){
      ctx.beginPath(); ctx.roundRect ? ctx.roundRect(cx - 5.5, cyy - 9, 11, 18, 2.5) : ctx.rect(cx - 5.5, cyy - 9, 11, 18); ctx.stroke();
      ctx.beginPath(); ctx.arc(cx, cyy + 5.5, 1.3, 0, Math.PI * 2); ctx.fill();
    } else if(kind === 'web'){
      ctx.beginPath(); ctx.arc(cx, cyy, 8.5, 0, Math.PI * 2); ctx.stroke();
      ctx.beginPath(); ctx.ellipse(cx, cyy, 3.8, 8.5, 0, 0, Math.PI * 2); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(cx - 8.5, cyy); ctx.lineTo(cx + 8.5, cyy); ctx.stroke();
    } else {
      ctx.beginPath(); ctx.arc(cx, cyy - 3, 6.5, Math.PI * 0.85, Math.PI * 2.15); ctx.lineTo(cx, cyy + 9); ctx.closePath(); ctx.fill();
      ctx.fillStyle = navy; ctx.beginPath(); ctx.arc(cx, cyy - 3, 2.4, 0, Math.PI * 2); ctx.fill();
    }
  }
  const contactW = boxX - tX - 70;
  const contacts = [
    ['phone', st.company.phones],
    ['web', st.company.email || 'www.jcmultimedia.online'],
    ['pin', st.company.address]
  ].filter(c => c[1]);
  contacts.forEach(([k, v]) => {
    cy += 22;
    icon(k, tX + 31, cy);
    ctx.fillStyle = ink; ctx.font = '15px Poppins'; ctx.textAlign = 'left';
    ctx.fillText(fitText(v, contactW, '15px Poppins'), tX + 58, cy + 5);
    cy += 22;
  });

  /* ---------- Merci + signature (à droite) ---------- */
  const sx = boxX + boxW/2;
  ctx.textAlign = 'center'; ctx.fillStyle = ink; ctx.font = '800 40px Poppins';
  ctx.fillText('Merci !', sx, contactTop + 4);
  if(st.signerName){
    fitFont(st.signerName, boxW - 30, 600, 40, '"Dancing Script", "Brush Script MT", cursive', 20);
    ctx.fillStyle = navy;
    ctx.fillText(st.signerName, sx, contactTop + 82);
  }
  ctx.strokeStyle = '#9A9AA6'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(sx - 120, contactTop + 98); ctx.lineTo(sx + 120, contactTop + 98); ctx.stroke();
  ctx.font = '15px Poppins'; ctx.fillStyle = '#222';
  ctx.fillText(st.signerName ? 'Signature — ' + company : 'Signature', sx, contactTop + 122);

  /* ---------- Pied de page : formes diagonales ---------- */
  ctx.fillStyle = orange;
  ctx.beginPath();
  ctx.moveTo(W * 0.20, H); ctx.lineTo(W * 0.66, H - 118); ctx.lineTo(W * 0.69, H - 92); ctx.lineTo(W * 0.31, H);
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = navy;
  ctx.beginPath();
  ctx.moveTo(W * 0.52, H); ctx.lineTo(W, H - 128); ctx.lineTo(W, H);
  ctx.closePath(); ctx.fill();
}

/* ---------- Reçu à partir d'une commande du site ---------- */
async function recuDecorateOrderButtons(){
  const btns = document.querySelectorAll('.recu-order-btn');
  if(!btns.length || !SUPABASE_ENABLED) return;
  try{
    const ids = [...btns].map(b => Number(b.dataset.orderId)).filter(Boolean);
    const { data, error } = await db.from('receipts').select('order_id, number').in('order_id', ids);
    if(error) throw error;
    const byOrder = {};
    (data || []).forEach(r => { if(!byOrder[r.order_id] || r.number > byOrder[r.order_id]) byOrder[r.order_id] = r.number; });
    btns.forEach(b => {
      const n = byOrder[Number(b.dataset.orderId)];
      if(n){ b.textContent = `🧾 Voir le reçu ${recuNumberLabel(n)}`; b.classList.remove('btn-wa'); b.classList.add('btn-ghost'); }
    });
  }catch(e){ console.warn('recuDecorateOrderButtons:', e); }
}

async function recuFromOrder(orderId){
  if(!SUPABASE_ENABLED) return;
  const id = Number(orderId);
  const btn = document.querySelector(`.recu-order-btn[data-order-id="${id}"]`);
  const label = btn ? btn.textContent : '';
  if(btn){ btn.disabled = true; btn.textContent = 'Préparation…'; }
  try{
    recuLoadLogo();
    if(!recuState){
      await recuLoadHistory();
      const last = recuHistory[0];
      recuState = recuBlankState(last ? recuFromRow(last) : null);
    }
    // Un reçu existe déjà pour cette commande : on l'ouvre au lieu d'en créer un second.
    const { data: existing, error: exErr } = await db.from('receipts').select('*, orders(code)')
      .eq('order_id', id).order('number', { ascending:false }).limit(1);
    if(exErr) throw exErr;
    if(existing && existing.length){
      recuState = recuFromRow(existing[0]);
    } else {
      const [{ data: order, error: oErr }, { data: lines, error: lErr }] = await Promise.all([
        db.from('orders').select('id, code, customer_name, customer_phone, customer_address, total').eq('id', id).single(),
        db.from('order_items').select('name, code, quantity, unit_price, customized').eq('order_id', id).order('id', { ascending:true })
      ]);
      if(oErr) throw oErr;
      if(lErr) throw lErr;
      const items = (lines || []).map(l => ({
        name: l.name || '',
        description: [l.code, l.customized ? 'personnalisé' : ''].filter(Boolean).join(' · '),
        qty: Number(l.quantity) || 0,
        price: Number(l.unit_price) || 0
      }));
      const base = recuBlankState(recuState);
      base.orderId = order.id;
      base.orderCode = order.code || null;
      base.clientName = order.customer_name || '';
      base.clientPhone = order.customer_phone || '';
      base.clientAddress = order.customer_address || '';
      base.currency = 'HTG';
      if(items.length) base.items = items;
      // Aligne le total du reçu sur celui de la commande (frais ou remise éventuels)
      const linesTotal = items.reduce((a,i) => a + i.qty * i.price, 0);
      const diff = Math.round(((Number(order.total) || 0) - linesTotal) * 100) / 100;
      if(diff > 0.009) base.deliveryFee = diff;
      else if(diff < -0.009) base.discount = -diff;
      recuState = base;
    }
    showAdminTab('recus');
    const tab = document.getElementById('adminTab-recus');
    if(tab) window.scrollTo({ top: tab.offsetTop - 20, behavior:'smooth' });
  }catch(e){
    console.error('recuFromOrder:', e);
    showToast("Impossible de préparer le reçu — réessayez.");
  }finally{
    if(btn){ btn.disabled = false; btn.textContent = label; }
  }
}

/* =========================================================
   COMMANDE WHATSAPP → LIEN DE PAIEMENT (onglet « Liens de paiement »)
   L'admin saisit la commande prise sur WhatsApp ; elle est
   enregistrée comme une commande normale (code JC-…), avec un
   jeton secret. Le client reçoit le lien /payer/<jeton> et paie
   par MonCash/Natcash ; le webhook confirme automatiquement.
   ========================================================= */
const PAY_LINK_BASE = 'https://jcmultimedia.online/payer/';
let payLinkForm = null;

function payLinkBlankForm(){
  return {
    clientName:'', clientPhone:'', clientAddress:'', delivery:'Récupérer sur place',
    lines:[{ name:'', qty:1, price:0, kind:'services', catalogId:null, code:null }],
    deliveryFee:0, details:''
  };
}
function payLinkUrl(token){ return PAY_LINK_BASE + token; }
function payLinkWaNumber(phone){
  let d = String(phone || '').replace(/\D/g, '');
  if(d.length === 8) d = '509' + d;
  return d;
}
function payLinkTotal(f){
  return f.lines.reduce((a,l) => a + (Number(l.qty)||0) * (Number(l.price)||0), 0) + (Number(f.deliveryFee)||0);
}

/* ---- Onglet « Liens de paiement » ---- */
let PAYLINKS_FILTER = 'all';
let PAYLINKS_LOADING = null;
function renderAdminPayLinks(){
  PAYLINKS_LOADING = payLinksRenderTab();
  return PAYLINKS_LOADING;
}
async function payLinksRenderTab(){
  const el = document.getElementById('adminTab-paylinks');
  if(!el) return;
  if(typeof SUPABASE_ENABLED !== 'undefined' && !SUPABASE_ENABLED){
    el.innerHTML = `<div class="admin-note">⚠️ Nécessite que Supabase soit configuré.</div>`;
    return;
  }
  el.innerHTML = `
    <div class="admin-note">Pour un client qui commande sur WhatsApp : créez la commande ici, puis envoyez-lui le lien. Il paie par MonCash ou Natcash, et le paiement est confirmé automatiquement.</div>
    <div id="payLinkAdmin"></div>
    <div class="modal-actions" style="margin-bottom:16px;">
      <button class="btn btn-primary" onclick="payLinkOpenForm()">+ Nouveau lien de paiement</button>
    </div>
    <div id="payLinksList"><p class="card-sub">Chargement…</p></div>`;
  await payLinksRenderList();
}
async function payLinksRenderList(){
  const box = document.getElementById('payLinksList');
  if(!box) return;
  try{
    const { data: orders, error } = await db.from('orders')
      .select('id, code, created_at, customer_name, customer_phone, total, status, pay_token')
      .eq('source', 'whatsapp').order('created_at', { ascending:false }).limit(300);
    if(error) throw error;
    const list = (orders || []).filter(o => o.pay_token);
    const ids = list.map(o => o.id);
    const paid = new Set();
    if(ids.length){
      const { data: pays } = await db.from('payments').select('order_id, status').in('order_id', ids);
      (pays || []).forEach(p => { if(p.status === 'Confirmé') paid.add(p.order_id); });
    }
    const stateOf = o => (o.status === 'Annulée' || o.status === 'Refusée') ? 'cancelled' : (paid.has(o.id) ? 'paid' : 'pending');
    const counts = { all: list.length, pending: 0, paid: 0, cancelled: 0 };
    list.forEach(o => counts[stateOf(o)]++);
    const filters = [['all','Tous'],['pending','En attente'],['paid','Payés'],['cancelled','Annulés']];
    const shown = PAYLINKS_FILTER === 'all' ? list : list.filter(o => stateOf(o) === PAYLINKS_FILTER);
    const badge = st => st === 'paid' ? '<span class="paylink-badge paid">✅ Payé</span>'
      : st === 'cancelled' ? '<span class="paylink-badge cancelled">Annulé</span>'
      : '<span class="paylink-badge pending">⏳ En attente</span>';
    box.innerHTML = `
      <div class="paylink-filters">
        ${filters.map(([k,l]) => `<button class="opt-btn ${PAYLINKS_FILTER===k?'selected':''}" onclick="payLinksSetFilter('${k}')">${l} (${counts[k]})</button>`).join('')}
      </div>
      ${shown.length ? shown.map(o => `
        <div class="paylink-row">
          <div class="paylink-row-head">
            <strong>${escapeHtml(o.code || '—')}</strong> ${badge(stateOf(o))}
          </div>
          <div class="card-sub">${escapeHtml(o.customer_name || 'Client')} · ${escapeHtml(o.customer_phone || '')}</div>
          <div class="card-sub">${escapeHtml(formatHTG(Number(o.total) || 0))} · ${new Date(o.created_at).toLocaleDateString('fr-FR')}</div>
          ${stateOf(o) === 'pending' ? `<button class="btn btn-ghost" style="margin-top:10px;" onclick="payLinkShare(${Number(o.id)})">🔗 Renvoyer / copier le lien</button>` : ''}
        </div>`).join('') : `<p class="card-sub">${list.length ? 'Aucun lien dans cette catégorie.' : 'Aucun lien de paiement pour le moment.'}</p>`}`;
  }catch(e){
    console.error('payLinksRenderList:', e);
    box.innerHTML = `<p class="card-sub">Impossible de charger les liens de paiement.</p>`;
  }
}
function payLinksSetFilter(k){ PAYLINKS_FILTER = k; payLinksRenderList(); }

function payLinkOpenForm(){
  payLinkForm = payLinkBlankForm();
  payLinkRenderForm();
  const el = document.getElementById('payLinkAdmin');
  if(el) el.scrollIntoView({ behavior:'smooth', block:'start' });
}
function payLinkClose(){
  payLinkForm = null;
  const el = document.getElementById('payLinkAdmin');
  if(el) el.innerHTML = '';
}

function payLinkRenderForm(){
  const el = document.getElementById('payLinkAdmin');
  if(!el || !payLinkForm) return;
  const f = payLinkForm;
  const field = (id, label, value, extra='') => `<div class="form-field"><label for="${id}">${label}</label><input type="text" id="${id}" value="${escapeHtml(String(value ?? ''))}" ${extra} oninput="payLinkRead()"></div>`;
  el.innerHTML = `
    <div class="paylink-card">
      <h3 style="margin:0 0 6px;">Nouvelle commande WhatsApp</h3>
      <p class="card-sub" style="margin:0 0 12px;">La commande est enregistrée avec un code JC-…, puis tu envoies le lien au client pour qu'il paie par MonCash ou Natcash.</p>
      ${field('pl-name', 'Nom du client *', f.clientName)}
      ${field('pl-phone', 'Téléphone WhatsApp du client *', f.clientPhone, 'inputmode="tel" placeholder="Ex : 3443 2139"')}
      ${field('pl-address', 'Adresse (optionnel)', f.clientAddress)}
      <div class="form-field">
        <label>Livraison</label>
        <div style="display:flex; gap:6px; flex-wrap:wrap;">
          ${['Récupérer sur place','Se faire livrer'].map(o => `<button type="button" class="opt-btn ${f.delivery===o?'selected':''}" onclick="payLinkSetDelivery('${o}')">${o}</button>`).join('')}
        </div>
      </div>
      <h3 class="recu-h">Articles / services</h3>
      <div id="payLinkLines"></div>
      <div class="form-field">
        <select onchange="payLinkAddFromCatalog(this.value); this.value='';">${recuCatalogOptions()}</select>
      </div>
      <button type="button" class="btn btn-ghost btn-block" onclick="payLinkAddLine()">+ Ajouter une ligne vide</button>
      <div class="form-field" style="margin-top:12px;"><label for="pl-fee">Frais de livraison (HTG)</label><input type="number" min="0" step="1" id="pl-fee" value="${Number(f.deliveryFee)||0}" oninput="payLinkRead()"></div>
      <div class="form-field"><label for="pl-details">Détails / notes (optionnel)</label><textarea id="pl-details" rows="3" oninput="payLinkRead()" style="width:100%; padding:11px 12px; border-radius:10px; border:1px solid var(--line); background:var(--surface2); font-family:inherit;">${escapeHtml(f.details)}</textarea></div>
      <div class="admin-note" id="payLinkTotalNote"></div>
      <div class="recu-actions">
        <button class="btn btn-primary btn-block" id="payLinkCreateBtn" onclick="payLinkCreate()">Créer la commande et le lien</button>
        <button class="btn btn-ghost btn-block" onclick="payLinkClose()">Annuler</button>
      </div>
    </div>`;
  payLinkRenderLines();
  payLinkUpdateTotal();
}

function payLinkRenderLines(){
  const box = document.getElementById('payLinkLines');
  if(!box) return;
  const f = payLinkForm;
  box.innerHTML = f.lines.map((l, i) => `
    <div class="recu-item">
      ${f.lines.length > 1 ? `<button type="button" class="recu-remove" onclick="payLinkRemoveLine(${i})">retirer</button>` : ''}
      <div class="form-field"><label>Article / service${l.code ? ` <span class="item-code-tag">${escapeHtml(l.code)}</span>` : ''}</label><input type="text" value="${escapeHtml(l.name)}" oninput="payLinkSetLine(${i},'name',this.value)"></div>
      <div class="recu-row">
        <div class="form-field"><label>Quantité</label><input type="number" min="1" step="1" value="${l.qty}" oninput="payLinkSetLine(${i},'qty',this.value)"></div>
        <div class="form-field"><label>Prix unitaire (HTG)</label><input type="number" min="0" step="1" value="${l.price}" oninput="payLinkSetLine(${i},'price',this.value)"></div>
      </div>
    </div>`).join('');
}
function payLinkRead(){
  const f = payLinkForm; if(!f) return;
  const v = id => { const e = document.getElementById(id); return e ? e.value : ''; };
  f.clientName = v('pl-name').trim();
  f.clientPhone = v('pl-phone').trim();
  f.clientAddress = v('pl-address').trim();
  f.deliveryFee = parseFloat(v('pl-fee')) || 0;
  f.details = v('pl-details');
  payLinkUpdateTotal();
}
function payLinkSetDelivery(o){ payLinkRead(); payLinkForm.delivery = o; payLinkRenderForm(); }
function payLinkSetLine(i, field, value){
  const l = payLinkForm.lines[i]; if(!l) return;
  l[field] = (field === 'qty' || field === 'price') ? (parseFloat(value) || 0) : value;
  payLinkUpdateTotal();
}
function payLinkAddLine(){ payLinkRead(); payLinkForm.lines.push({ name:'', qty:1, price:0, kind:'services', catalogId:null, code:null }); payLinkRenderLines(); payLinkUpdateTotal(); }
function payLinkRemoveLine(i){ payLinkRead(); payLinkForm.lines.splice(i,1); if(!payLinkForm.lines.length) payLinkAddLine(); payLinkRenderLines(); payLinkUpdateTotal(); }
function payLinkAddFromCatalog(value){
  if(!value) return;
  payLinkRead();
  const sep = value.indexOf(':');
  const kind = value.slice(0, sep), id = value.slice(sep + 1);
  const item = ((CATALOG && CATALOG[kind]) || []).find(x => String(x.id) === id);
  if(!item) return;
  const line = {
    name: item.name || '', qty: 1,
    price: kind === 'services' ? Number(item.startingPrice)||0 : Number(item.price)||0,
    kind, catalogId: item.id, code: item.code || null
  };
  const lines = payLinkForm.lines;
  const last = lines[lines.length - 1];
  if(last && !last.name && !Number(last.price)) lines[lines.length - 1] = line; else lines.push(line);
  payLinkRenderLines(); payLinkUpdateTotal();
}
function payLinkUpdateTotal(){
  const el = document.getElementById('payLinkTotalNote');
  if(el) el.innerHTML = `Total à payer : <strong>${escapeHtml(formatHTG(payLinkTotal(payLinkForm)))}</strong> (≈ ${escapeHtml(formatUSD(payLinkTotal(payLinkForm)))})`;
}

async function payLinkCreate(){
  payLinkRead();
  const f = payLinkForm;
  if(!f.clientName){ showToast('Indiquez le nom du client'); return; }
  if(payLinkWaNumber(f.clientPhone).length < 8){ showToast('Indiquez le téléphone WhatsApp du client'); return; }
  const lines = f.lines.filter(l => l.name.trim() && (Number(l.qty)||0) > 0);
  if(!lines.length){ showToast('Ajoutez au moins un article avec un nom'); return; }
  const fee = Number(f.deliveryFee) || 0;
  const allLines = fee > 0 ? [...lines, { name:'Frais de livraison', qty:1, price:fee, kind:'services', catalogId:null, code:null }] : lines;
  const total = Math.round(allLines.reduce((a,l) => a + l.qty * l.price, 0) * 100) / 100;
  if(total < 20){ showToast('Le total doit être d\'au moins 20 HTG (minimum du paiement en ligne)'); return; }

  const btn = document.getElementById('payLinkCreateBtn');
  if(btn){ btn.disabled = true; btn.textContent = 'Création…'; }
  try{
    // Jeton secret de 40 caractères (fonctionne aussi sur les anciens téléphones)
    const bytes = crypto.getRandomValues(new Uint8Array(20));
    const token = Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
    const { data: order, error } = await db.from('orders').insert({
      customer_name: f.clientName,
      customer_phone: f.clientPhone,
      customer_address: f.clientAddress || null,
      items: allLines.map(l => ({ name: l.name.trim(), qty: Number(l.qty)||0, kind: l.kind || 'services', customized: false })),
      total,
      exchange_rate: SETTINGS.exchangeRate,
      payment: 'Lien de paiement',
      delivery: f.delivery,
      details: f.details.trim() || null,
      pay_token: token,
      source: 'whatsapp'
    }).select('id, code').single();
    if(error) throw error;
    const { error: itemsErr } = await db.from('order_items').insert(allLines.map(l => ({
      order_id: order.id,
      catalog_item_id: l.catalogId || null,
      kind: l.kind || 'services',
      code: l.code || null,
      name: l.name.trim(),
      unit_price: Number(l.price)||0,
      is_estimate: false,
      quantity: Number(l.qty)||0,
      customized: false,
      line_total: Math.round((Number(l.qty)||0) * (Number(l.price)||0) * 100) / 100
    })));
    if(itemsErr){
      // Sans lignes, la page de paiement serait vide : on annule la commande.
      await db.from('orders').delete().eq('id', order.id);
      throw itemsErr;
    }
    payLinkForm = null;
    await renderAdminPayLinks();
    payLinkShowResult({ id: order.id, code: order.code, token, total, name: f.clientName, phone: f.clientPhone });
  }catch(e){
    console.error('payLinkCreate:', e);
    showToast("Échec de la création — vérifiez votre connexion.");
    if(btn){ btn.disabled = false; btn.textContent = 'Créer la commande et le lien'; }
  }
}

function payLinkMessage(r){
  return `Bonjour ${r.name || ''}, voici le lien pour payer votre commande ${r.code} chez JC Multimedia (${formatHTG(r.total)}) par MonCash ou Natcash :\n${payLinkUrl(r.token)}\n\nMerci pour votre confiance !`;
}
function payLinkShowResult(r){
  const el = document.getElementById('payLinkAdmin');
  if(!el) return;
  const url = payLinkUrl(r.token);
  const wa = payLinkWaNumber(r.phone);
  window.__payLinkLast = r;
  el.innerHTML = `
    <div class="paylink-card">
      <h3 style="margin:0 0 6px;">✅ Commande ${escapeHtml(r.code || '')} créée</h3>
      <p class="card-sub" style="margin:0 0 10px;">${escapeHtml(r.name || '')} — ${escapeHtml(formatHTG(r.total))}</p>
      <div class="form-field"><label>Lien de paiement</label><input type="text" readonly value="${escapeHtml(url)}" onclick="this.select()"></div>
      <div class="recu-actions">
        <a class="btn btn-wa btn-block" href="https://wa.me/${wa}?text=${encodeURIComponent(payLinkMessage(r))}" target="_blank" rel="noopener">Envoyer au client sur WhatsApp</a>
        <button class="btn btn-ghost btn-block" onclick="payLinkCopy()">Copier le lien</button>
        <button class="btn btn-ghost btn-block" onclick="payLinkClose()">Fermer</button>
      </div>
    </div>`;
  el.scrollIntoView({ behavior:'smooth', block:'start' });
}
async function payLinkCopy(){
  const r = window.__payLinkLast; if(!r) return;
  try{ await navigator.clipboard.writeText(payLinkUrl(r.token)); showToast('Lien copié'); }
  catch(e){ showToast('Copie impossible : appuie sur le lien puis copie-le'); }
}
async function payLinkShare(orderId){
  const panel = document.getElementById('adminTab-paylinks');
  if(panel && panel.style.display === 'none'){
    showAdminTab('paylinks');
    if(PAYLINKS_LOADING) await PAYLINKS_LOADING;
  }
  try{
    const { data, error } = await db.from('orders').select('id, code, total, customer_name, customer_phone, pay_token').eq('id', orderId).single();
    if(error) throw error;
    if(!data.pay_token){ showToast('Cette commande n\'a pas de lien de paiement'); return; }
    payLinkShowResult({ id: data.id, code: data.code, token: data.pay_token, total: Number(data.total)||0, name: data.customer_name, phone: data.customer_phone });
  }catch(e){
    console.error(e);
    showToast('Impossible de charger le lien');
  }
}
